contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling transfer with arbitrary arrays
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length || _tos.length == 0);
        // observe public getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        // make the deciding call: since transfer requires msg.sender == from, and here
        // msg.sender will be this contract, the call will succeed only when before_from == address(this).
        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read values after call
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule:
        // - The public state variables 'from' and 'caddress' are not modified by transfer, so they remain equal.
        // - Additionally, if the call did not revert, it must be the case that the contract's from equals msg.sender (this contract).
        // Combine into one assert relating parameters, observed values, and revert flag.
        assert(after_from == before_from && after_caddress == before_caddress && (reverted || before_from == address(this)));
    }

    receive() external payable { }
}

