contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller will be this contract (msg.sender for c calls). We take arrays to forward to c.transfer.
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length, "inputs length mismatch");
        require(_tos.length > 0, "must have at least one recipient");
        // observe public values before
        address before_from = c.from();
        address before_caddress = c.caddress();

        // perform the call and record if it reverted
        bool reverted = false;
        try c.transfer(_tos, v) returns (bool ret) {
            // if returns, require ret == true per contract implementation; do nothing else
        } catch {
            reverted = true;
        }

        // After call, public getters must remain equal to before values if the call did not revert.
        // Also, because contract C requires msg.sender to be the hard-coded owner, when this test
        // (whose msg.sender to c is this contract) is not that owner the call must revert.
        // We express a general rule: if not reverted then public getters unchanged and the call
        // could only have succeeded when this contract is that owner (we check by comparing
        // the known getter to msg.sender).
        assert(
            (!reverted && c.from() == before_from && c.caddress() == before_caddress && c.from() == address(this))
            || (reverted && c.from() == before_from && c.caddress() == before_caddress && c.from() != address(this)))
        ;
    }
    receive() external payable { }
}

